#define SIZE 8
typedef struct entry {
    char *key;
    int value;
    struct entry *next;
} entry;
entry *table[SIZE];

unsigned hash(const char *s) {
    unsigned h = 0;
    for (; *s; s++)
        h = h * 31 + (unsigned char)*s;
    return h % SIZE;
}

void put(const char *k, int v) {
    entry *e = malloc(sizeof *e);
    e->key = malloc(strlen(k) + 1);
    strcpy(e->key, k);
    e->value = v;
    unsigned i = hash(k);
    e->next = table[i];
    table[i] = e;
}

int get(const char *k, int *out) {
    entry *e = table[hash(k)];
    for (; e; e = e->next)
        if (strcmp(e->key, k) == 0) {
            *out = e->value;
            return 1;
        }
    return 0;
}
